                String string = strings[i];
                passed = testable.run(unsorted, sorted, string);
                if (!passed) {
                    System.err.println(testable.getInput());
                    System.err.println(testable.getName()+" failed.");
                    return false;
                }
            } catch (NullPointerException e) {
                System.err.println(testable.getInput());
                throw e;
            }
            firstTimeThru = false;
        }
        if (debugTime && debugMemory)
