        m_fc = m_ras.getChannel();
        m_tmpHeaderBuf = DBBPool.allocateDirect(SEGMENT_HEADER_BYTES);

        if (truncate) {
            initNumEntries(0, 0);
        }
        m_fc.position(SEGMENT_HEADER_BYTES);

