    public String[] getExcludeFieldNames() {
        return this.excludeFieldNames.clone();
    }

    /**
     * Sets the field names to exclude.
     *
     * @param excludeFieldNamesParam
     *            The field names to exclude from the diff or {@code null}.
     * @return {@code this}
     * @since 3.13.0
     */
    public ReflectionDiffBuilder<T> setExcludeFieldNames(final String... excludeFieldNamesParam) {
        if (excludeFieldNamesParam == null) {
            this.excludeFieldNames = ArrayUtils.EMPTY_STRING_ARRAY;
        } else {
            this.excludeFieldNames = processExcludeFieldNames(excludeFieldNamesParam);
        }
        return this;
    }

    private String[] processExcludeFieldNames(final String... excludeFieldNamesParam) {
        // clone and remove nulls
        return ArraySorter.sort(ReflectionToStringBuilder.toNoNullStringArray(excludeFieldNamesParam));
    }
}

