                start = Math.max('0', start);
                end = Math.min('z' + 1, end);
            } else if (numbers) {
                // just numbers, no letters
                start = Math.max('0', start);
                end = Math.min('9' + 1, end);
            } else if (letters) {
                // just letters, no numbers
                start = Math.max('A', start);
                end = Math.min('z' + 1, end);
